<?php
namespace App\Domain\GhostEvents\Services; use App\Domain\GhostEvents\Models\GhostEvent; use Illuminate\Support\Facades\Cache;
class GhostEventBundleService { public function build(GhostEvent $event):array{return Cache::remember('ghost-event-bundle:'.$event->id.':'.($event->updated_at?->timestamp??0),now()->addMinutes(5),function()use($event){$ghosts=$event->benchmarks()->with(['replay','run.publicShare'])->get()->filter(fn($b)=>$b->replay?->benchmark_eligible&&($b->run?->publicShare?->isViewableByPublic()??false))->take(min(4,max(1,$event->max_visible_ghosts?:2)))->map(fn($b)=>['slot'=>$b->slot,'label'=>$b->label,'durationMs'=>$b->duration_ms,'digest'=>$b->digest,'replay'=>['id'=>$b->replay_record_id,'digest'=>$b->digest,'expiresAt'=>now()->addMinutes(10)->toIso8601String()]])->values();return ['version'=>(string)($event->updated_at?->timestamp??1),'event'=>['id'=>$event->id,'slug'=>$event->slug,'name'=>$event->name],'conditions'=>['courseId'=>$event->course_id,'environmentId'=>$event->environment_id,'weatherPresetId'=>$event->weather_preset_id,'physicsVersion'=>$event->physics_version],'maxVisibleGhosts'=>min(4,max(1,$event->max_visible_ghosts?:2)),'ghosts'=>$ghosts,'rewardRules'=>$event->reward_configuration_json??[],'expiresAt'=>now()->addMinutes(10)->toIso8601String()];});} }
